function openCEOReport(type){try{localStorage.setItem('fn-ceo-print-snapshot',JSON.stringify({scenario:state.quarterScenario,generatedAt:new Date().toISOString()}))}catch{openDialog('Report not prepared','<p>Browser storage is unavailable. Enable local storage and retry so the report uses your current assumptions.</p>');return}const w=window.open('ceo-report.html?type='+encodeURIComponent(type),'_blank');if(!w)openDialog('Open print-ready report','<p>Your browser blocked the report tab. Open the report using the link below, then select Print / Save as PDF.</p><a class="btn" href="ceo-report.html?type='+encodeURIComponent(type)+'" target="_blank" rel="noopener">Open report</a>')}
